1	export async function reserve(db, sku) {
2	  const row = await db.get(sku);
3	  if (row.available < 1) return false;
4	  await db.set(sku, {available: row.available - 1});
5	  return true;
6	}
7

1	export function store() {
2	  let available = 1;
3	  return { async get() { return {available}; }, async set(sku, row) { available = row.available; }, value() { return available; } };
4	}
